// Original practice material. Software behaviour below is fictional training context.
const readingLevels=[
 {id:0,name:'基础',detail:'短句、提示与日常消息',goal:'找准动作、对象、条件和限制'},
 {id:1,name:'实用',detail:'文档、问题报告与协作',goal:'读清细节，写出完整说明'},
 {id:2,name:'进阶',detail:'长文、方案与观点',goal:'识别论点、权衡与隐含条件'}
];
const readingUnits=[];
function U(id,level,title,genre,paragraphs,phrases,questions,writing){
 const prepared=questions.map(([q,options,answer,why],index)=>{
  let seed=[...id+index].reduce((n,c)=>(Math.imul(n,31)+c.charCodeAt(0))>>>0,17);
  const order=options.map((_,i)=>i);
  for(let i=order.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[order[i],order[j]]=[order[j],order[i]]}
  return {q,options:order.map(i=>options[i]),answer:order.indexOf(answer),why};
 });
 readingUnits.push({id,level,title,genre,paragraphs:paragraphs.map(([en,zh])=>({en,zh})),phrases,questions:prepared,writing});
}
